UNLOCK TABLES;
DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payments` (
  `id` char(36) NOT NULL,
  `tenant_id` varchar(255) DEFAULT NULL,
  `patient_id` char(36) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `payment_method` enum('cash','card','bank_transfer','other') NOT NULL DEFAULT 'cash',
  `payment_date` date NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `is_synced` tinyint(1) NOT NULL DEFAULT 0,
  `invoice_id` char(36) DEFAULT NULL,
  `treatment_session_id` char(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `payments_patient_id_foreign` (`patient_id`),
  KEY `payments_tenant_id_index` (`tenant_id`),
  KEY `payments_tenant_id_payment_date_index` (`tenant_id`,`payment_date`),
  KEY `payments_invoice_id_foreign` (`invoice_id`),
